(()=>{ /* 🌌 OMNI-GALAXY MULTI-MEDIA STUDIOS PLATFORM: THE NAME AND THE ART (v254). The platform's own name and its three pieces of art, placed
   through the app, and its website, www.omni-galaxy.com, one tap from every screen:
   • THE LOGO (the lightning wordmark) heads the landing page, the footer, the Legal & Safety page, Services, Sports, Current News,
     the Stock Market, the Knowledge Library and the sign-in card.
   • THE FULL BANNER (the wordmark in its starfield) heads your page and the social pages.
   • THE GALAXY WHEEL WITH THE LOGO greets every visit on the agreement card.
   • THE GALAXY WHEEL (the ring of letters around the spiral) heads LuvMyZodiac and is the cover of every profile that has no cover photo.
   • 🌐 www.omni-galaxy.com: on the landing page, in every footer, in the Menu, on Legal & Safety and in Find. */
 const IMG={logo:'data:image/webp;base64,',logoSm:'data:image/webp;base64,',banner:'data:image/webp;base64,',wheelLogo:'data:image/webp;base64,',wheel:'data:image/webp;base64,',icon:'data:image/webp;base64,'};
 window.OGIMG=IMG; const SITE='https://www.omni-galaxy.com', NAME='Omni-Galaxy Multi-Media Studios Platform';
 const $=id=>document.getElementById(id);
 const css=document.createElement('style'); css.textContent=`
html body .mast .ddlogo.ddlogo{width:min(640px,100%)!important;opacity:1!important;margin:-4px auto 0!important;filter:drop-shadow(0 0 14px rgba(190,110,255,.45))!important}
@media (max-width:760px){html body .mast .ddlogo.ddlogo{width:min(calc(100vw - 110px),420px)!important}}
#footBrand .ddlogo{opacity:1!important;filter:none!important;max-height:90px}
.ogWeb{display:inline-flex;align-items:center;gap:6px;min-height:34px;padding:0 14px;margin:6px 4px 2px;border-radius:999px;background:rgba(127,255,255,.12);border:1px solid rgba(127,255,255,.55);color:#9ff!important;font:800 13.5px system-ui,sans-serif;letter-spacing:.04em;text-decoration:none!important}
.ogWeb:hover{background:rgba(127,255,255,.24)}
.ogFootLink{display:inline-flex;align-items:center;gap:6px;margin:2px 4px;color:#9ff!important;font:800 12.5px system-ui,sans-serif;text-decoration:none!important}
.ogFootLink img{height:22px;width:auto}
:is(#kLegal,#kServices,#kSports,#kNews,#kMarket,#kKnow)::before{content:"";display:block;height:clamp(84px,13vw,150px);max-width:620px;margin:0 auto 6px;background:url(${IMG.logoSm}) center/contain no-repeat}
#zodDock::before{content:"";display:block;height:clamp(150px,24vw,320px);margin:0 0 12px;border-radius:4px 22px 4px 22px;background:linear-gradient(0deg,rgba(10,6,24,.55),rgba(10,6,24,0) 45%),url(${IMG.wheel}) center 40%/cover no-repeat;box-shadow:0 10px 30px rgba(0,0,0,.45)}
#kAgree .agCard::before{content:"";display:block;height:clamp(150px,30vw,230px);margin:-6px -6px 10px;border-radius:4px 16px 4px 16px;background:url(${IMG.wheelLogo}) center 18%/cover no-repeat}
#kAcct::before{content:"";display:block;height:clamp(90px,14vw,170px);max-width:1100px;margin:0 auto 10px;border-radius:4px 18px 4px 18px;background:#020108 url(${IMG.banner}) center/contain no-repeat;box-shadow:0 8px 24px rgba(0,0,0,.4)}
#kAgree .agCard{max-height:calc(100vh - 32px);overflow:auto}
.ogMenuHead{grid-column:1/-1;order:-10;display:flex;flex-direction:column;align-items:center;gap:2px;margin:4px 0 8px}
.ogMenuHead img{width:min(320px,90%);height:auto}
.ogMenuHead a{color:#9ff!important;font:800 12.5px system-ui,sans-serif;text-decoration:none!important}`; document.head.appendChild(css);
 const link=(cls,txt)=>{ const a=document.createElement('a'); a.href=SITE; a.target='_blank'; a.rel='noopener'; a.className=cls; a.setAttribute('data-noul',''); a.innerHTML=txt; return a; };
 function place(){
  /* the landing page: the website under the brand lines */
  const ap=document.querySelector('.mast .presents.appn'); if(ap&&!ap.parentElement.querySelector('.ogWeb')) ap.insertAdjacentElement('afterend',link('ogWeb','🌐 www.omni-galaxy.com ↗'));
  /* every footer: the logo and the website */
  document.querySelectorAll('.ocFoot').forEach(f=>{ if(!f.querySelector(':scope > .ogFootLink')) f.appendChild(link('ogFootLink','<img src="'+IMG.logoSm+'" alt="">🌐 www.omni-galaxy.com ↗')); });
  /* the legal page: who runs it, with the website */
  const lg=$('kLegal'); if(lg&&!lg.hidden){ const top=lg.querySelector('.lgIn > p'); if(top&&!lg.querySelector('.ogWeb')) top.insertAdjacentElement('afterend',link('ogWeb','🌐 '+NAME+' · www.omni-galaxy.com ↗')); }
  /* the agreement card: the website */
  const ag=document.querySelector('#kAgree .agCard'); if(ag&&!ag.querySelector('.ogWeb')){ const r=ag.querySelector('.agRow'); if(r) r.insertAdjacentElement('beforebegin',link('ogWeb','🌐 www.omni-galaxy.com ↗')); }
  /* the Menu: the logo and the website at its head */
  document.querySelectorAll('#tourTab').forEach(m=>{ if(m.querySelector('.ogMenuHead')) return; const h=document.createElement('div'); h.className='ogMenuHead'; h.innerHTML='<img src="'+IMG.logoSm+'" alt="'+NAME+'">'; h.appendChild(link('','🌐 www.omni-galaxy.com ↗')); m.insertBefore(h,m.firstChild); });
  /* the tab's icon */
  if(!document.querySelector('link[rel="icon"][data-og]')){ const l=document.createElement('link'); l.rel='icon'; l.type='image/webp'; l.href=IMG.icon; l.dataset.og='1'; document.head.appendChild(l); }
 }
 place(); setInterval(place,1500);
 (window.KFINDX=window.KFINDX||[]).push(add=>{ add('You','🌐','www.omni-galaxy.com: the website of the '+NAME,'Website',()=>{ const a=link('',''); document.body.appendChild(a); a.click(); a.remove(); }); });
 window.KBRAND={NAME,SITE,IMG};
})();
